READ = 0.1                                  # a cache hit costs 10% of the normal price
options = {"5-minute cache": 1.25, "1-hour cache": 2.0}   # write multipliers

breakeven = {}
for name, write_mult in options.items():
    for n in range(1, 21):
        uncached = n * 1.0
        cached = write_mult + (n - 1) * READ
        if cached < uncached:
            breakeven[name] = (n, round(cached, 2), uncached)
            break

for name, (n, cached, uncached) in breakeven.items():
    print(f"{name}: pays off at call {n} ({cached} vs {uncached} prompt-costs)")
